/**
 * 03 练习册的四本分类本：语音 / 词汇 / 结构 / 表达。
 * 每本对应一张独立题卷 —— 题目从对应知识书的练习题库汇聚而来，
 * 页面上只做题、不讲知识，和 02 知识库的书页分开。
 */
export interface PracticeTrack {
  id: string;
  title: string;
  titleZh: string;
  subtitleZh: string;
  /** 题库来源：知识书的 id */
  bookId: string;
  accent: string;
}

export const PRACTICE_TRACKS: PracticeTrack[] = [
  {
    id: "sound",
    title: "Sound Drills",
    titleZh: "语音",
    subtitleZh: "音位、音节与语音过程，语言学题库集中练。",
    bookId: "knowledge-linguistics",
    accent: "#7f6d5f",
  },
  {
    id: "words",
    title: "Word Drills",
    titleZh: "词汇",
    subtitleZh: "构词、词义辨析与高频搭配，词汇书题库集中练。",
    bookId: "knowledge-vocabulary",
    accent: "#b28b42",
  },
  {
    id: "structure",
    title: "Structure Drills",
    titleZh: "结构",
    subtitleZh: "句法、段落与雅思写作，写作书题库集中练。",
    bookId: "knowledge-writing",
    accent: "#8a6d9c",
  },
  {
    id: "expression",
    title: "Expression Drills",
    titleZh: "表达",
    subtitleZh: "翻译策略与译法选择，翻译书题库集中练。",
    bookId: "knowledge-translation",
    accent: "#5f7d8a",
  },
];

export function practiceTrackById(id: string | undefined) {
  return PRACTICE_TRACKS.find((track) => track.id === id);
}

/** 知识书页上「去练习册」用的反向对照。 */
export const TRACK_BY_BOOK: Record<string, string> = Object.fromEntries(
  PRACTICE_TRACKS.map((track) => [track.bookId, track.id]),
);
